NFQ_main():
  k = 0
  init_MLP() -> Q_0
  Do {
    generate pattern set P = {(input_l, target_l), l = 1, ..., |D|}
      where input_l = (s_l, u_l)
            target_l = c(s_l, u_l, s'_l) + gamma * min_b Q_k(s'_l, b)
    Rprop_training(P) -> Q_{k+1}
    k := k + 1
  } While (k < N)
